"""Subscription pricing."""


def _volume(price, seats):
    return price * 85 // 100 if seats >= 20 else price


def _flat(price, seats):
    return price * 40 // 100


class _Quote:
    """Pricing mechanics shared by all plans; the differences are plugged in as steps."""

    def __init__(self, plan, unit_steps=(), total_steps=()):
        self.plan = plan
        self.unit_steps = list(unit_steps)
        self.total_steps = list(total_steps)

    def unit_price(self):
        price = self.plan.base_cents
        for step in self.unit_steps:
            price = step(price, self.plan.seats)
        return price

    def total(self):
        amount = self.unit_price() * self.plan.seats
        for step in self.total_steps:
            amount = step(amount)
        return amount


def _describe(plan):
    return "%s x%d = %d" % (plan.label, plan.seats, plan.total())


class Tariff:
    """Per-seat pricing: unit price times seats."""

    label = "standard"
    base_cents = 1500

    def __init__(self, seats):
        self.seats = seats
        self._quote = _Quote(self, [], [])

    def unit_price(self):
        return self._quote.unit_price()

    def total(self):
        return self._quote.total()

    def describe(self):
        return _describe(self)


class BulkTariff:
    """Cheaper unit price from 20 seats."""

    label = "bulk"
    base_cents = 1500

    def __init__(self, seats):
        self.seats = seats
        self._quote = _Quote(self, [_volume], [])

    def unit_price(self):
        return self._quote.unit_price()

    def total(self):
        return self._quote.total()

    def describe(self):
        return _describe(self)


class SchoolTariff:
    """A flat percentage of the (volume) unit price for schools."""

    label = "school"
    base_cents = 1500

    def __init__(self, seats):
        self.seats = seats
        self._quote = _Quote(self, [_volume, _flat], [])

    def unit_price(self):
        return self._quote.unit_price()

    def total(self):
        return self._quote.total()

    def describe(self):
        return _describe(self)

