"""Subscription pricing."""


class Tariff:
    """Per-seat pricing: unit price times seats."""

    label = "standard"
    base_cents = 1500

    def __init__(self, seats):
        self.seats = seats

    def unit_price(self):
        return self.base_cents

    def total(self):
        return self.unit_price() * self.seats

    def describe(self):
        return "%s x%d = %d" % (self.label, self.seats, self.total())


class BulkTariff(Tariff):
    """Cheaper unit price from 20 seats."""

    label = "bulk"

    def unit_price(self):
        price = super().unit_price()
        if self.seats >= 20:
            price = price * 85 // 100
        return price


class SchoolTariff(BulkTariff):
    """A flat percentage of the (volume) unit price for schools."""

    label = "school"

    def unit_price(self):
        return super().unit_price() * 40 // 100

