import json
import unittest

from tariffs.core import Tariff, BulkTariff, SchoolTariff


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Tariff(case["seats"]),
        "volume": lambda: BulkTariff(case["seats"]),
        "edu": lambda: SchoolTariff(case["seats"]),
    }
    plan = makers[kind]()
    rows = []
    for seats in case["sizes"]:
        plan.seats = seats
        rows.append([plan.unit_price(), plan.total(), plan.describe()])
    plan.base_cents = case["base"]
    return {
        "first": [plan.label, plan.seats],
        "rows": rows,
        "repriced": [plan.unit_price(), plan.total(), plan.describe()],
        "grant": getattr(plan, "grant", None),
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"seats\": 60, \"grant\": 5000, \"sizes\": [1, 10, 5, 200], \"base\": 2500}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"first\": [\"standard\", 200], \"rows\": [[1500, 1500, \"standard x1 = 1500\"], [1500, 15000, \"standard x10 = 15000\"], [1500, 7500, \"standard x5 = 7500\"], [1500, 300000, \"standard x200 = 300000\"]], \"repriced\": [2500, 500000, \"standard x200 = 500000\"], \"grant\": null}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"volume\", \"seats\": 60, \"grant\": 100000, \"sizes\": [24], \"base\": 700}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"first\": [\"bulk\", 24], \"rows\": [[1275, 30600, \"bulk x24 = 30600\"]], \"repriced\": [595, 14280, \"bulk x24 = 14280\"], \"grant\": null}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"edu\", \"seats\": 60, \"grant\": 5000, \"sizes\": [9], \"base\": 1000}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"first\": [\"school\", 9], \"rows\": [[600, 5400, \"school x9 = 5400\"]], \"repriced\": [400, 3600, \"school x9 = 3600\"], \"grant\": null}"))


if __name__ == '__main__':
    unittest.main()

