import json
import unittest

from cachekit.core import Cache, JournalCache, BoundedCache


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Cache(),
        "audit": lambda: JournalCache(),
        "quota": lambda: BoundedCache(case["max_keys"]),
    }
    store = makers[kind]()
    results = []
    for op in case["ops"]:
        name, args = op[0], op[1:]
        try:
            results.append(getattr(store, name)(*args))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "data": store.data,
        "reads": store.reads,
        "state": {a: getattr(store, a) for a in ("log", "max_keys", "ttl", "now", "born") if hasattr(store, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"max_keys\": 3, \"ttl\": 1, \"ops\": [[\"tick\", 3], [\"get\", \"a\"], [\"delete\", \"b\"], [\"put\", \"d\", 3], [\"delete\", \"a\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"ERR AttributeError 'Cache' object has no attribute 'tick'\", null, null, null, null], \"data\": {\"d\": 3}, \"reads\": 1, \"state\": {}}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"audit\", \"max_keys\": 1, \"ttl\": 3, \"ops\": [[\"tick\", 1], [\"tick\", 3], [\"tick\", 3], [\"put\", \"a\", 3], [\"get\", \"c\"], [\"put\", \"c\", 6], [\"tick\", 1], [\"tick\", 3], [\"put\", \"d\", 2], [\"put\", \"b\", 1], [\"put\", \"d\", 2]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"ERR AttributeError 'JournalCache' object has no attribute 'tick'\", \"ERR AttributeError 'JournalCache' object has no attribute 'tick'\", \"ERR AttributeError 'JournalCache' object has no attribute 'tick'\", null, null, null, \"ERR AttributeError 'JournalCache' object has no attribute 'tick'\", \"ERR AttributeError 'JournalCache' object has no attribute 'tick'\", null, null, null], \"data\": {\"a\": 3, \"c\": 6, \"d\": 2, \"b\": 1}, \"reads\": 1, \"state\": {\"log\": [[\"put\", \"a\"], [\"put\", \"c\"], [\"put\", \"d\"], [\"put\", \"b\"], [\"put\", \"d\"]]}}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"quota\", \"max_keys\": 2, \"ttl\": 1, \"ops\": [[\"put\", \"b\", 7], [\"put\", \"b\", 1], [\"delete\", \"a\"], [\"put\", \"a\", 4], [\"put\", \"a\", 3], [\"put\", \"c\", 2], [\"put\", \"a\", 8], [\"tick\", 2], [\"tick\", 1], [\"put\", \"a\", 4], [\"get\", \"d\"], [\"get\", \"c\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, null, null, null, null, \"ERR KeyError 'cache full: 2 keys'\", null, \"ERR AttributeError 'BoundedCache' object has no attribute 'tick'\", \"ERR AttributeError 'BoundedCache' object has no attribute 'tick'\", null, null, null], \"data\": {\"b\": 1, \"a\": 4}, \"reads\": 2, \"state\": {\"log\": [[\"put\", \"b\"], [\"put\", \"b\"], [\"delete\", \"a\"], [\"put\", \"a\"], [\"put\", \"a\"], [\"put\", \"a\"], [\"put\", \"a\"]], \"max_keys\": 2}}"))


if __name__ == '__main__':
    unittest.main()

