import json
import unittest

from kvstore.core import Store, AuditedStore, QuotaStore, ExpiringStore


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Store(),
        "audit": lambda: AuditedStore(),
        "quota": lambda: QuotaStore(case["max_keys"]),
        "expiry": lambda: ExpiringStore(case["max_keys"], case["ttl"]),
    }
    store = makers[kind]()
    results = []
    for op in case["ops"]:
        name, args = op[0], op[1:]
        try:
            results.append(getattr(store, name)(*args))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "data": store.data,
        "reads": store.reads,
        "state": {a: getattr(store, a) for a in ("log", "max_keys", "ttl", "now", "born") if hasattr(store, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"max_keys\": 2, \"ttl\": 1, \"ops\": [[\"tick\", 2], [\"put\", \"a\", 0], [\"get\", \"a\"], [\"put\", \"a\", 7], [\"put\", \"c\", 0], [\"put\", \"c\", 6], [\"put\", \"b\", 2], [\"tick\", 2], [\"put\", \"d\", 0], [\"tick\", 3]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"ERR AttributeError 'Store' object has no attribute 'tick'\", null, 0, null, null, null, null, \"ERR AttributeError 'Store' object has no attribute 'tick'\", null, \"ERR AttributeError 'Store' object has no attribute 'tick'\"], \"data\": {\"a\": 7, \"c\": 6, \"b\": 2, \"d\": 0}, \"reads\": 1, \"state\": {}}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"audit\", \"max_keys\": 2, \"ttl\": 1, \"ops\": [[\"put\", \"d\", 2], [\"tick\", 3], [\"tick\", 3], [\"get\", \"d\"], [\"delete\", \"b\"], [\"delete\", \"a\"], [\"put\", \"c\", 8], [\"tick\", 3]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, \"ERR AttributeError 'AuditedStore' object has no attribute 'tick'\", \"ERR AttributeError 'AuditedStore' object has no attribute 'tick'\", 2, null, null, null, \"ERR AttributeError 'AuditedStore' object has no attribute 'tick'\"], \"data\": {\"d\": 2, \"c\": 8}, \"reads\": 1, \"state\": {\"log\": [[\"put\", \"d\"], [\"delete\", \"b\"], [\"delete\", \"a\"], [\"put\", \"c\"]]}}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"quota\", \"max_keys\": 2, \"ttl\": 2, \"ops\": [[\"put\", \"b\", 7], [\"put\", \"c\", 0], [\"put\", \"b\", 9], [\"put\", \"c\", 1], [\"get\", \"a\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, null, null, null, null], \"data\": {\"b\": 9, \"c\": 1}, \"reads\": 1, \"state\": {\"log\": [[\"put\", \"b\"], [\"put\", \"c\"], [\"put\", \"b\"], [\"put\", \"c\"]], \"max_keys\": 2}}"))


if __name__ == '__main__':
    unittest.main()

