import json
import unittest

from kvstore.core import Store, AuditedStore, QuotaStore


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Store(),
        "audit": lambda: AuditedStore(),
        "quota": lambda: QuotaStore(case["max_keys"]),
    }
    store = makers[kind]()
    results = []
    for op in case["ops"]:
        name, args = op[0], op[1:]
        try:
            results.append(getattr(store, name)(*args))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "data": store.data,
        "reads": store.reads,
        "state": {a: getattr(store, a) for a in ("log", "max_keys", "ttl", "now", "born") if hasattr(store, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"max_keys\": 3, \"ttl\": 1, \"ops\": [[\"get\", \"b\"], [\"put\", \"a\", 3], [\"get\", \"d\"], [\"tick\", 1], [\"put\", \"b\", 9], [\"get\", \"c\"], [\"put\", \"b\", 2]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, null, null, \"ERR AttributeError 'Store' object has no attribute 'tick'\", null, null, null], \"data\": {\"a\": 3, \"b\": 2}, \"reads\": 3, \"state\": {}}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"audit\", \"max_keys\": 3, \"ttl\": 2, \"ops\": [[\"get\", \"a\"], [\"put\", \"d\", 0], [\"put\", \"c\", 2], [\"put\", \"c\", 9], [\"get\", \"d\"], [\"put\", \"c\", 4], [\"put\", \"c\", 2], [\"put\", \"c\", 0], [\"put\", \"b\", 2]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, null, null, null, 0, null, null, null, null], \"data\": {\"d\": 0, \"c\": 0, \"b\": 2}, \"reads\": 2, \"state\": {\"log\": [[\"put\", \"d\"], [\"put\", \"c\"], [\"put\", \"c\"], [\"put\", \"c\"], [\"put\", \"c\"], [\"put\", \"c\"], [\"put\", \"b\"]]}}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"quota\", \"max_keys\": 1, \"ttl\": 2, \"ops\": [[\"get\", \"d\"], [\"tick\", 3], [\"put\", \"a\", 1], [\"get\", \"b\"], [\"delete\", \"b\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, \"ERR AttributeError 'QuotaStore' object has no attribute 'tick'\", null, null, null], \"data\": {\"a\": 1}, \"reads\": 2, \"state\": {\"log\": [[\"put\", \"a\"], [\"delete\", \"b\"]], \"max_keys\": 1}}"))


if __name__ == '__main__':
    unittest.main()

