from mailer.core import Outbox, BoundedOutbox, MailOutbox, DigestOutbox


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Outbox(case["name"]),
        "throttled": lambda: BoundedOutbox(case["name"], case["limit"]),
        "mail": lambda: MailOutbox(case["name"], case["limit"], case["domain"]),
        "digest": lambda: DigestOutbox(case["name"], case["limit"], case["domain"], case["size"]),
    }
    ch = makers[kind]()
    results = []
    for text in case["messages"]:
        try:
            results.append(ch.send(text))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "sent": ch.sent,
        "formatted": ch.format("probe"),
        "delivered": ch.deliver("raw"),
        "attrs": {a: getattr(ch, a) for a in ("name", "limit", "domain", "size", "buffer") if hasattr(ch, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"name\": \"ops\", \"limit\": 3, \"domain\": \"corp.test\", \"size\": 3, \"messages\": [\"retry 3\", \"disk full\", \"disk full\"]}")
