import json
import unittest

from outbound.core import Sender, LimitedSender, SmtpSender, BatchSender


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Sender(case["name"]),
        "throttled": lambda: LimitedSender(case["name"], case["limit"]),
        "mail": lambda: SmtpSender(case["name"], case["limit"], case["domain"]),
        "digest": lambda: BatchSender(case["name"], case["limit"], case["domain"], case["size"]),
    }
    ch = makers[kind]()
    results = []
    for text in case["messages"]:
        try:
            results.append(ch.send(text))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "sent": ch.sent,
        "formatted": ch.format("probe"),
        "delivered": ch.deliver("raw"),
        "attrs": {a: getattr(ch, a) for a in ("name", "limit", "domain", "size", "buffer") if hasattr(ch, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"name\": \"ops\", \"limit\": 1, \"domain\": \"example.org\", \"size\": 3, \"messages\": []}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [], \"sent\": [\"raw\"], \"formatted\": \"probe\", \"delivered\": 1, \"attrs\": {\"name\": \"ops\"}}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"throttled\", \"name\": \"alerts\", \"limit\": 5, \"domain\": \"corp.test\", \"size\": 3, \"messages\": [\"retry 3\", \"paid\", \"retry 3\", \"ok\"]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 2, 3, 4], \"sent\": [\"retry 3\", \"paid\", \"retry 3\", \"ok\", \"raw\"], \"formatted\": \"probe\", \"delivered\": 5, \"attrs\": {\"name\": \"alerts\", \"limit\": 5}}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"mail\", \"name\": \"billing\", \"limit\": 2, \"domain\": \"example.org\", \"size\": 2, \"messages\": [\"paid\", \"retry 3\", \"paid\"]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 2, \"ERR RuntimeError too many messages (max 2)\"], \"sent\": [\"MAIL: paid <billing@example.org>\", \"MAIL: retry 3 <billing@example.org>\", \"raw\"], \"formatted\": \"MAIL: probe <billing@example.org>\", \"delivered\": 3, \"attrs\": {\"name\": \"billing\", \"limit\": 2, \"domain\": \"example.org\"}}"))


if __name__ == '__main__':
    unittest.main()

