        self.name = name
        self.sent = []

    def format(self, text):
        return self.prefix + text

    def deliver(self, line):
        self.sent.append(line)
        return len(self.sent)

    def send(self, text):
        return self.deliver(self.format(text))


class LimitedSender(Sender):
    """Refuses to send more than `limit` messages."""

    def __init__(self, name, limit):
        super().__init__(name)
        self.limit = limit

    def send(self, text):
        if len(self.sent) >= self.limit:
            raise RuntimeError("too many messages (max %d)" % self.limit)
        return super().send(text)


class SmtpSender(LimitedSender):
    """Adds a mail prefix and a sender address."""

    prefix = "MAIL: "

    def __init__(self, name, limit, domain):
        super().__init__(name, limit)
        self.domain = domain

    def format(self, text):
        return super().format(text) + " <%s@%s>" % (self.name, self.domain)

