import json
import unittest

from outbound.core import Sender, LimitedSender, SmtpSender


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Sender(case["name"]),
        "throttled": lambda: LimitedSender(case["name"], case["limit"]),
        "mail": lambda: SmtpSender(case["name"], case["limit"], case["domain"]),
    }
    ch = makers[kind]()
    results = []
    for text in case["messages"]:
        try:
            results.append(ch.send(text))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "sent": ch.sent,
        "formatted": ch.format("probe"),
        "delivered": ch.deliver("raw"),
        "attrs": {a: getattr(ch, a) for a in ("name", "limit", "domain", "size", "buffer") if hasattr(ch, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"name\": \"ops\", \"limit\": 1, \"domain\": \"corp.test\", \"size\": 3, \"messages\": [\"paid\", \"ok\"]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 2], \"sent\": [\"paid\", \"ok\", \"raw\"], \"formatted\": \"probe\", \"delivered\": 3, \"attrs\": {\"name\": \"ops\"}}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"throttled\", \"name\": \"ops\", \"limit\": 1, \"domain\": \"corp.test\", \"size\": 2, \"messages\": [\"paid\", \"retry 3\"]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, \"ERR RuntimeError too many messages (max 1)\"], \"sent\": [\"paid\", \"raw\"], \"formatted\": \"probe\", \"delivered\": 2, \"attrs\": {\"name\": \"ops\", \"limit\": 1}}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"mail\", \"name\": \"alerts\", \"limit\": 3, \"domain\": \"corp.test\", \"size\": 2, \"messages\": [\"ok\", \"disk full\", \"paid\", \"retry 3\"]}")
