import json
import unittest

from cachekit.core import Cache, JournalCache, BoundedCache, TtlCache


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Cache(),
        "audit": lambda: JournalCache(),
        "quota": lambda: BoundedCache(case["max_keys"]),
        "expiry": lambda: TtlCache(case["max_keys"], case["ttl"]),
    }
    store = makers[kind]()
    results = []
    for op in case["ops"]:
        name, args = op[0], op[1:]
        try:
            results.append(getattr(store, name)(*args))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "data": store.data,
        "reads": store.reads,
        "state": {a: getattr(store, a) for a in ("log", "max_keys", "ttl", "now", "born") if hasattr(store, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"max_keys\": 3, \"ttl\": 3, \"ops\": [[\"put\", \"c\", 5], [\"put\", \"a\", 0], [\"get\", \"d\"], [\"put\", \"c\", 3], [\"tick\", 2], [\"put\", \"a\", 9], [\"tick\", 3], [\"put\", \"d\", 4], [\"put\", \"d\", 8], [\"delete\", \"d\"], [\"put\", \"c\", 2]]}")
