        "results": results,
        "data": store.data,
        "reads": store.reads,
        "state": {a: getattr(store, a) for a in ("log", "max_keys", "ttl", "now", "born") if hasattr(store, a)},
    }

def _norm(x):
    return json.loads(json.dumps(x))

def _outcome(case):
    try:
        return _norm(run_case(copy.deepcopy(case)))
    except Exception as e:
        return {"raises": type(e).__name__}

