import json
import unittest

from registry.core import Registry, TrackedRegistry, LimitedRegistry, LeaseRegistry


def run_case(case):
    kind = case["kind"]
    makers = {
        "base": lambda: Registry(),
        "audit": lambda: TrackedRegistry(),
        "quota": lambda: LimitedRegistry(case["max_keys"]),
        "expiry": lambda: LeaseRegistry(case["max_keys"], case["ttl"]),
    }
    store = makers[kind]()
    results = []
    for op in case["ops"]:
        name, args = op[0], op[1:]
        try:
            results.append(getattr(store, name)(*args))
        except Exception as e:
            results.append("ERR %s %s" % (type(e).__name__, e))
    return {
        "results": results,
        "data": store.data,
        "reads": store.reads,
        "state": {a: getattr(store, a) for a in ("log", "max_keys", "ttl", "now", "born") if hasattr(store, a)},
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"kind\": \"base\", \"max_keys\": 3, \"ttl\": 2, \"ops\": [[\"get\", \"d\"], [\"tick\", 2], [\"put\", \"c\", 2], [\"get\", \"c\"], [\"put\", \"c\", 9], [\"get\", \"c\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, \"ERR AttributeError 'Registry' object has no attribute 'tick'\", null, 2, null, 9], \"data\": {\"c\": 9}, \"reads\": 3, \"state\": {}}"))

    def test_example_2(self):
        case = json.loads("{\"kind\": \"audit\", \"max_keys\": 2, \"ttl\": 1, \"ops\": [[\"get\", \"a\"], [\"put\", \"d\", 7], [\"put\", \"c\", 0], [\"put\", \"b\", 9], [\"get\", \"d\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, null, null, null, 7], \"data\": {\"d\": 7, \"c\": 0, \"b\": 9}, \"reads\": 2, \"state\": {\"log\": [[\"put\", \"d\"], [\"put\", \"c\"], [\"put\", \"b\"]]}}"))

    def test_example_3(self):
        case = json.loads("{\"kind\": \"quota\", \"max_keys\": 1, \"ttl\": 4, \"ops\": [[\"get\", \"a\"], [\"put\", \"d\", 1], [\"get\", \"d\"], [\"put\", \"b\", 2], [\"get\", \"a\"], [\"get\", \"a\"], [\"put\", \"a\", 4], [\"tick\", 3]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, null, 1, \"ERR KeyError 'registry limit 1 reached'\", null, null, \"ERR KeyError 'registry limit 1 reached'\", \"ERR AttributeError 'LimitedRegistry' object has no attribute 'tick'\"], \"data\": {\"d\": 1}, \"reads\": 4, \"state\": {\"log\": [[\"put\", \"d\"]], \"max_keys\": 1}}"))


if __name__ == '__main__':
    unittest.main()
